    ) {
        Icon(
            imageVector = icon,
            contentDescription = null,
            tint = contentColor,
            modifier = Modifier.size(dimensionResource(R.dimen.list_options_icon_size))
        )
        Text(
            text = text,
            color = contentColor,
            style = MaterialTheme.typography.labelSmall.copy(baselineShift = null),
        )
    }
}

