    var completedDays by rememberSaveable {
        mutableIntStateOf(0)
    }
    var remainingDays by rememberSaveable {
        mutableIntStateOf(0)
    }
    LaunchedEffect(key1 = fixedDeposit) {
        completedDays = System.currentTimeMillis().getDifferenceBetweenDays(fixedDeposit.startDate.time)
