    first: Boolean = false,
    last: Boolean = false,
    required: Boolean = false,
    enabled: Boolean = true,
    errorMessage: String? = null,
) {

    var showPassword by remember { mutableStateOf(false) }
    var focused by remember { mutableStateOf(false) }
    val interactionSource = remember { MutableInteractionSource() }
    val isError = errorMessage != null
    val indicatorColors = sectionTextInputIndicatorColors(isError)

    SectionRow(
        first = first,
        last = last,
        padding = SectionDefaults.verticalPaddingValues(
            first = first,
            last = last,
            start = 22.dp,
            top = 4.dp,
            end = 14.dp,
            bottom = 10.dp
        ),
        focused = focused,
        modifier = Modifier.alpha(if (enabled) 1f else 0.5f),
        tone = if (isError) {
            Tone.NEGATIVE
        } else {
            Tone.NEUTRAL
        }
    ) {
        Column(modifier = Modifier.weight(1f)) {

            SectionTextInputSlidingLabel(
                label = label,
                required = required
            )

            SecureTextField(
                state = password,
                textObfuscationMode = if (showPassword) {
                    TextObfuscationMode.Visible
                } else {
                    TextObfuscationMode.RevealLastTyped
                },
                modifier = Modifier
                    .sectionTextInput(
                        interactionSource = interactionSource,
                        indicatorColors = indicatorColors,
                        onFocusChanged = {
                            focused = it
                        }
                    )
                    .semantics { contentType = ContentType.Password },
                textStyle = MaterialTheme.typography.headlineLarge.copy(fontSize = fontSize),
                interactionSource = interactionSource,
                keyboardOptions = KeyboardOptions(
                    imeAction = ImeAction.Next,
