@Composable
fun CitySearchDialog(
    onCitySelected: (CityResult) -> Unit,
    onDismiss: () -> Unit,
) {
    var query by remember { mutableStateOf("") }
    val results = remember { mutableStateListOf<CityResult>() }
    var isLoading by remember { mutableStateOf(false) }
    var searchJob by remember { mutableStateOf<Job?>(null) }
    val scope = rememberCoroutineScope()

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.dialog_city_search)) },
        text = {
            Column(modifier = Modifier.fillMaxWidth()) {
                OutlinedTextField(
                    value = query,
                    onValueChange = { q ->
                        query = q
                        searchJob?.cancel()
                        if (q.length >= 3) {
                            searchJob = scope.launch {
                                delay(500)
                                searchCity(q) { list ->
                                    results.clear()
                                    results.addAll(list)
                                    isLoading = false
                                }
                            }
                        } else {
                            results.clear()
                        }
                    },
                    label = { Text(stringResource(R.string.label_city_name)) },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                )

                Spacer(modifier = Modifier.height(8.dp))

                if (isLoading) {
                    CircularProgressIndicator(modifier = Modifier.padding(16.dp))
                }

                LazyColumn(modifier = Modifier.height(200.dp)) {
                    items(results) { city ->
                        Text(
                            text = city.displayName,
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { onCitySelected(city) }
                                .padding(vertical = 8.dp, horizontal = 4.dp),
                            style = MaterialTheme.typography.bodyMedium,
                        )
                    }
                }
            }
        },
        confirmButton = {
            TextButton(onClick = onDismiss) { Text(stringResource(R.string.btn_cancel)) }
        },
    )
}

