private fun SdkLegendItem(
    item: SdkDistribution,
    appLabel: String,
    appsLabel: String,
    onClick: () -> Unit,
) {
    val color = item.sdkVersion.apiToComposeColor()
    Surface(
        onClick = onClick,
        modifier = Modifier.width(112.dp),
        shape = RoundedCornerShape(16.dp),
        color = color.copy(alpha = 0.1f),
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(4.dp),
        ) {
            Surface(shape = RoundedCornerShape(8.dp), color = color) {
                Text(
                    text = item.sdkVersion.toString(),
                    modifier = Modifier.padding(horizontal = 9.dp, vertical = 4.dp),
                    style = MaterialTheme.typography.labelMedium,
                    fontWeight = FontWeight.Bold,
                    color = Color.White,
                )
            }
            Text(
                text = item.sdkVersion.apiToVersionName(),
                style = MaterialTheme.typography.labelSmall,
                fontWeight = FontWeight.SemiBold,
                color = color,
                maxLines = 1,
            )
            Text(
                text = "${item.appCount} ${if (item.appCount == 1) appLabel else appsLabel}",
                style = MaterialTheme.typography.bodySmall,
                fontWeight = FontWeight.SemiBold,
            )
            Text(
                text = "${(item.percentage * 100).toInt()}%",
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}
